<?php
require_once 'config/layout.php';require_once 'config/guidance.php';
require_teacher();$user=current_user();$teacher=(int)$user['id'];$school=$user['school_id'];$error='';$message='';
$learner=filter_var($_GET['learner']??null,FILTER_VALIDATE_INT)?:0;
if($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf($_POST['csrf']??null);$learner=filter_var($_POST['learner_id']??null,FILTER_VALIDATE_INT)?:0;
 if(!teacher_can_view($teacher,$learner)){http_response_code(403);exit('Guidance access is unavailable or consent has been revoked.');}
 try {
  if(($_POST['action']??'')==='note') {
   $note=input_text('note',3000);$next=input_text('next_action',500);$due=input_text('follow_up_on',10);
   if(!$note||!$next)throw new InvalidArgumentException('Add a brief guidance note and an agreed next action.');
   if($due && (!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$due)||!checkdate((int)substr($due,5,2),(int)substr($due,8,2),(int)substr($due,0,4))))throw new InvalidArgumentException('Enter a valid follow-up date.');
   db()->prepare('INSERT INTO counselling_notes(teacher_id,learner_id,school_id,note,next_action,follow_up_on) VALUES(?,?,?,?,?,?)')->execute([$teacher,$learner,$school,$note,$next,$due?:null]);
   audit_event('guidance_note_added','learner',$learner);$message='Guidance note saved.';
  } elseif(($_POST['action']??'')==='complete') {
   $id=filter_var($_POST['note_id']??null,FILTER_VALIDATE_INT)?:0;
   db()->prepare("UPDATE counselling_notes SET status='completed' WHERE id=? AND teacher_id=? AND learner_id=? AND school_id=?")->execute([$id,$teacher,$learner,$school]);
   audit_event('guidance_action_completed','learner',$learner);$message='Action marked complete.';
  } else throw new InvalidArgumentException('Unknown action.');
 } catch(InvalidArgumentException $ex){$error=$ex->getMessage();}
}
if($learner && !teacher_can_view($teacher,$learner)){http_response_code(403);exit('Guidance access is unavailable or consent has been revoked.');}
$names=['R'=>'Realistic','I'=>'Investigative','A'=>'Artistic','S'=>'Social','E'=>'Enterprising','C'=>'Conventional'];$counts=[];$population=0;$assessed=0;$schoolName='School not assigned';
if($school) {
 $q=db()->prepare('SELECT name FROM schools WHERE id=?');$q->execute([$school]);$schoolName=(string)$q->fetchColumn();
 $q=db()->prepare("SELECT COUNT(*) FROM users u JOIN user_security s ON s.user_id=u.id WHERE s.school_id=? AND u.role='learner'");$q->execute([$school]);$population=(int)$q->fetchColumn();
 $q=db()->prepare("SELECT LEFT(a.top_interest,1) AS dimension,COUNT(*) AS n FROM assessments a JOIN (SELECT user_id,MAX(id) AS id FROM assessments GROUP BY user_id) latest ON latest.id=a.id JOIN users u ON u.id=a.user_id JOIN user_security s ON s.user_id=u.id WHERE s.school_id=? AND u.role='learner' GROUP BY LEFT(a.top_interest,1)");$q->execute([$school]);
 foreach($q->fetchAll() as $row){$counts[$row['dimension']]=(int)$row['n'];$assessed+=(int)$row['n'];}
}
$aggregateRows=[['School','Measure','Value'],[$schoolName,'Learner population',$population>=5?(string)(intdiv($population,5)*5).'–'.(intdiv($population,5)*5+4):'Suppressed (fewer than 5)'],[$schoolName,'Learners with an assessment',$assessed>=5?(string)(intdiv($assessed,5)*5).'–'.(intdiv($assessed,5)*5+4):'Suppressed (fewer than 5)']];
foreach($names as $d=>$name){$n=$counts[$d]??0;$aggregateRows[]=[$schoolName,$name.' leading interest',$n>=5?(string)(intdiv($n,5)*5).'–'.(intdiv($n,5)*5+4):'Suppressed (fewer than 5)'];}
if(isset($_GET['export'])) {if(!$school){http_response_code(403);exit('School assignment required.');}audit_event('school_aggregate_exported','school',$school);export_csv('career-compass-school-aggregate.csv',$aggregateRows);}
$q=db()->prepare("SELECT l.id,l.full_name,l.grade,g.granted_at FROM teacher_grants g JOIN users l ON l.id=g.learner_id JOIN user_security s ON s.user_id=l.id WHERE g.teacher_id=? AND g.revoked_at IS NULL AND s.school_id=? AND l.role='learner' ORDER BY l.full_name");$q->execute([$teacher,$school]);$learners=$q->fetchAll();
$selected=null;$profile=[];$scores=[];$recs=[];$notes=[];
if($learner) {
 $q=db()->prepare('SELECT id,full_name,grade FROM users WHERE id=?');$q->execute([$learner]);$selected=$q->fetch();$profile=profile_payload($learner);$a=latest_assessment($learner);$scores=json_array($a['riasec_scores']??null);
 $q=db()->prepare('SELECT r.career_title,r.match_score,r.explanation FROM recommendations r JOIN recommendation_details d ON d.recommendation_id=r.id WHERE d.run_id=(SELECT MAX(id) FROM recommendation_runs WHERE user_id=?) ORDER BY r.match_score DESC');$q->execute([$learner]);$recs=$q->fetchAll();
 $q=db()->prepare('SELECT * FROM counselling_notes WHERE learner_id=? AND teacher_id=? AND school_id=? ORDER BY id DESC LIMIT 100');$q->execute([$learner,$teacher,$school]);$notes=$q->fetchAll();audit_event('guidance_record_viewed','learner',$learner);
}
page_start('Educator guidance','teacher'); ?>
<main id="main" class="wide page-space"><div class="page-intro"><span class="eyebrow muted-eyebrow">EDUCATOR PORTAL</span><h1>Guidance for your school</h1><p><?= e($schoolName) ?>. Individual guidance requires a current, explicit learner permission and a matching administrator-confirmed school.</p></div>
<?php if($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif; ?><?php if($message): ?><div class="alert success" role="status"><?= e($message) ?></div><?php endif; ?>
<?php if(!$school): ?><section class="panel"><p>An administrator must assign your school before school statistics or learner records are available.</p></section><?php else: ?><section class="panel"><h2>School interest trends</h2><p>Only each learner's latest assessment is counted. Small groups are suppressed; other counts are shown in bands of five. These exploratory interests are not aptitude or employment forecasts.</p><div class="table-wrap"><table><thead><tr><th scope="col">Measure</th><th scope="col">Learners</th></tr></thead><tbody><?php foreach(array_slice($aggregateRows,1) as $row): ?><tr><th scope="row"><?= e($row[1]) ?></th><td><?= e($row[2]) ?></td></tr><?php endforeach; ?></tbody></table></div><p><a class="btn btn-outline" href="teacher.php?export=csv">Export protected aggregate CSV</a></p></section><?php endif; ?>
<div class="two-column"><section class="panel"><h2>Consenting learners</h2><?php if(!$learners): ?><p>No learners have currently enabled guidance access for you. Learners can manage permission in Account & privacy.</p><?php endif; ?><ul><?php foreach($learners as $l): ?><li><a href="teacher.php?learner=<?= (int)$l['id'] ?>"><?= e($l['full_name']) ?></a> <?= e($l['grade']) ?></li><?php endforeach; ?></ul></section><section class="panel"><h2>Guidance resources</h2><ul><li><a href="directory.php">Check sourced education pathways</a></li><li><a href="scholarships.php">Explore funding information</a></li><li><a href="careers.php">Use the career catalogue in a discussion</a></li></ul><p>Ask learners what matters to them, discuss the reasons behind recommendations, compare alternatives, and agree one practical next step. Avoid treating a RIASEC code as a fixed label.</p></section></div>
<?php if($selected): ?><section class="panel"><h2><?= e($selected['full_name']) ?> — guidance overview</h2><p>Current permission applies only to this school. Avoid recording sensitive personal information; learners can export notes about them.</p><h3>Profile shared by the learner</h3><dl><?php foreach(['subjects'=>'Subjects','aspirations'=>'Aspirations','skills'=>'Skills','preferences'=>'Preferences','guidance_needs'=>'Guidance needs'] as $key=>$label): ?><dt><strong><?= e($label) ?></strong></dt><dd><?= e(is_array($profile[$key]??null)?implode(', ',$profile[$key]):(string)($profile[$key]??'Not provided')) ?></dd><?php endforeach; ?></dl><h3>Interest profile</h3><?php if(!$scores): ?><p>No assessment completed.</p><?php else: ?><ul><?php foreach($names as $d=>$name): ?><li><?= e($name) ?>: <?= e((string)($scores[$d]??'Unknown')) ?>%</li><?php endforeach; ?></ul><?php endif; ?><h3>Latest recommendations</h3><?php if(!$recs): ?><p>No recommendation run available.</p><?php endif; ?><?php foreach($recs as $rec): ?><article><h4><?= e($rec['career_title']) ?> (<?= e($rec['match_score']) ?> exploratory match)</h4><p><?= e($rec['explanation']) ?></p></article><?php endforeach; ?></section>
<section class="panel"><h2>Record an agreed guidance action</h2><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="note"><input type="hidden" name="learner_id" value="<?= $learner ?>"><label>Brief discussion summary<textarea name="note" maxlength="3000" required rows="4"></textarea></label><label>Agreed next action<input name="next_action" maxlength="500" required></label><label>Follow-up date (optional)<input type="date" name="follow_up_on"></label><button class="btn btn-primary">Save guidance note</button></form></section>
<section class="panel"><h2>Your guidance notes</h2><?php if(!$notes): ?><p>No notes recorded by you for this learner.</p><?php endif; ?><?php foreach($notes as $note): ?><article class="programme-item"><p><?= nl2br(e($note['note'])) ?></p><p><strong>Next action:</strong> <?= e($note['next_action']) ?></p><p><?= e($note['follow_up_on']??'No follow-up date') ?> · <?= e($note['status']) ?> · <?= e($note['created_at']) ?></p><?php if($note['status']==='open'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="complete"><input type="hidden" name="learner_id" value="<?= $learner ?>"><input type="hidden" name="note_id" value="<?= (int)$note['id'] ?>"><button class="btn btn-outline">Mark action complete</button></form><?php endif; ?></article><?php endforeach; ?></section><?php endif; ?></main>
<?php page_end(); ?>
